/* ===== module: core/settings-search.js ===== */
/* Settings search — GRADUATED to permanent behaviour (user ruling
   2026-10-23: the Fork experiments framework is removed and every
   experiment that was switched on runs always). This module is what
   remains of core/fork-experiments.js: the registry, its Settings
   switches and every gate are deleted; the search itself — the one
   piece of that file that was a feature rather than framework —
   lives here and runs unconditionally. A stored `fork:experiments`
   preference is simply never read again.

   FORK v1.938 (UX audit #11): pure matcher first (tested): a section
   matches when its title or any of its text contains the query. The
   DOM side filters [data-section] cards, opens matching <details>
   while a query is active, and restores the pre-search open states
   when the query clears — the accordion's own persisted state is
   never written by searching. */
function forkSettingsMatches(text, query) {
  const q = String(query || '').trim().toLowerCase();
  if (!q) return true;
  return String(text || '').toLowerCase().includes(q);
}
if (typeof document !== 'undefined' && document.addEventListener) {
  let forkSearchSavedOpen = null;
  document.addEventListener('input', (event) => {
    if (event.target?.id !== 'forkSettingsSearch') return;
    const q = event.target.value;
    const sections = [...document.querySelectorAll('#settingsView [data-section]')];
    if (q.trim() && !forkSearchSavedOpen) {
      forkSearchSavedOpen = sections.map(s => s.tagName === 'DETAILS' ? s.open : null);
    }
    let anyMatch = false;
    sections.forEach((s, i) => {
      /* Nitpick R-30: an auth-gated section (data-auth-hidden, marked
         by renderSettings) stays hidden whatever the query says —
         search visibility never overrides the sign-in gate. */
      if (s.hasAttribute('data-auth-hidden')) { s.hidden = true; return; }
      const match = forkSettingsMatches(s.textContent, q);
      s.hidden = !match;
      if (match) anyMatch = true;
      if (s.tagName === 'DETAILS') {
        if (q.trim()) s.open = match;
        else if (forkSearchSavedOpen) s.open = !!forkSearchSavedOpen[i];
      }
    });
    if (!q.trim()) forkSearchSavedOpen = null;
    const none = document.querySelector('#forkSettingsNoMatch');
    if (none) none.hidden = anyMatch || !q.trim();
  });
}
